-- Copia mínima de autonomialab-db (comun + trozo de multibar) para probar en local.
create role anon nologin; create role authenticated nologin; create role service_role nologin;
create schema extensions; create extension pgcrypto schema extensions;
create schema privado; create schema comun; create schema multibar; create schema autonomialab;
grant usage on schema public to anon, authenticated, service_role;
create function privado.crypt(text,text) returns text language sql immutable strict set search_path=pg_catalog as $$ select extensions.crypt($1,$2) $$;
create function privado.digest(text,text) returns bytea language sql immutable strict set search_path=pg_catalog as $$ select extensions.digest($1,$2) $$;
create function privado.gen_random_bytes(int) returns bytea language sql strict set search_path=pg_catalog as $$ select extensions.gen_random_bytes($1) $$;
create function privado.gen_salt(text,int) returns text language sql strict set search_path=pg_catalog as $$ select extensions.gen_salt($1,$2) $$;
create table comun.negocios (id int generated by default as identity primary key, slug text unique not null check (slug ~ '^[a-z0-9][a-z0-9-]{1,39}$'), nombre text not null, zona_horaria text not null default 'Europe/Madrid', activo boolean not null default true, created_at timestamptz not null default now(), tipo text not null default 'multibar', idioma text not null default 'es', logo text, titular text, nif text, domicilio_fiscal text, correo_legal text, telefono_legal text, registro text, datos_extra jsonb not null default '{}', baja_at timestamptz);
create table comun.usuarios (id int generated always as identity primary key, negocio_id int not null references comun.negocios(id), email text not null, name text not null, active boolean not null default true, password_hash text not null, must_change_password boolean not null default true, failed_attempts int not null default 0, locked_until timestamptz, created_at timestamptz not null default now());
create unique index usuarios_email_idx on comun.usuarios (lower(email));
create table comun.sesiones (token_hash bytea primary key, usuario_id int not null references comun.usuarios(id), created_at timestamptz not null default now(), expires_at timestamptz not null);
create table comun.recuperaciones (token_hash bytea primary key, usuario_id int not null references comun.usuarios(id), created_at timestamptz not null default now(), expires_at timestamptz not null, usado_at timestamptz);
create table comun.productos_contratados (negocio_id int references comun.negocios(id), producto text, activo boolean not null default true, desde timestamptz not null default now(), primary key (negocio_id, producto));
alter table comun.negocios enable row level security; alter table comun.usuarios enable row level security;
alter table comun.sesiones enable row level security; alter table comun.recuperaciones enable row level security;
create table multibar.ajustes_multibar (negocio_id int primary key references comun.negocios(id), subtitulo text, ajustes jsonb);
create table multibar.personal_multibar (usuario_id int primary key references comun.usuarios(id), negocio_id int not null references comun.negocios(id), role text not null);
create view multibar.usuarios_multibar as select u.id,u.negocio_id,u.email,u.name,p.role,u.active,u.password_hash,u.must_change_password,u.failed_attempts,u.locked_until,u.created_at from comun.usuarios u join multibar.personal_multibar p on p.usuario_id=u.id;
create view multibar.bares_multibar as select n.id,n.slug,n.nombre,coalesce(a.subtitulo,'') subtitulo,n.zona_horaria,n.activo,coalesce(a.ajustes,'{}'::jsonb) ajustes,n.created_at from comun.negocios n left join multibar.ajustes_multibar a on a.negocio_id=n.id where n.tipo='multibar';
-- Login de MultiBar, copiado tal cual de Supabase (para comprobar que no ve cuentas de Gymbro).
CREATE FUNCTION privado.bar_json(p_bar_id integer) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public','comun','multibar','privado','pg_temp' AS $f$ select jsonb_build_object('slug', slug, 'nombre', nombre) from bares_multibar where id = p_bar_id $f$;
CREATE FUNCTION public.personal_entrar(p_email text, p_password text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','comun','multibar','privado','pg_temp' AS $f$
declare s usuarios_multibar; v_token text;
begin
  select * into s from usuarios_multibar where lower(email) = lower(btrim(coalesce(p_email, ''))) for update;
  if not found then perform privado.crypt(coalesce(p_password, ''), privado.gen_salt('bf', 10)); return jsonb_build_object('error', 'CREDENCIALES'); end if;
  if not s.active or s.password_hash <> privado.crypt(coalesce(p_password, ''), s.password_hash) then return jsonb_build_object('error', 'CREDENCIALES'); end if;
  v_token := encode(privado.gen_random_bytes(32), 'hex');
  insert into comun.sesiones (token_hash, usuario_id, expires_at) values (privado.digest(v_token, 'sha256'), s.id, now() + interval '16 hours');
  return jsonb_build_object('token', v_token, 'rol', s.role, 'bar', privado.bar_json(s.negocio_id));
end $f$;
CREATE FUNCTION public.personal_salir(p_token text) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path TO 'public','comun','multibar','privado','pg_temp' AS $f$ delete from comun.sesiones where token_hash = privado.digest(coalesce(p_token, ''), 'sha256'); $f$;
CREATE FUNCTION privado.plataforma_de_token(p_token text) RETURNS comun.usuarios LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','comun','multibar','privado','pg_temp' AS $f$
declare u comun.usuarios;
begin
  if p_token is null or length(p_token) <> 64 then raise exception 'SESION_CADUCADA'; end if;
  select us.* into u from comun.sesiones se join comun.usuarios us on us.id = se.usuario_id join comun.negocios n on n.id = us.negocio_id
   where se.token_hash = privado.digest(p_token, 'sha256') and se.expires_at > now() and us.active and n.activo and n.tipo = 'plataforma';
  if not found then raise exception 'SESION_CADUCADA'; end if;
  return u;
end $f$;
CREATE FUNCTION public.plataforma_entrar(p_email text, p_password text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','comun','multibar','privado','pg_temp' AS $f$
declare u comun.usuarios; v_token text;
begin
  select us.* into u from comun.usuarios us join comun.negocios n on n.id = us.negocio_id
   where lower(us.email) = lower(btrim(coalesce(p_email, ''))) and n.tipo = 'plataforma' and n.activo for update of us;
  if not found then return jsonb_build_object('error', 'CREDENCIALES'); end if;
  if not u.active or u.password_hash <> privado.crypt(coalesce(p_password, ''), u.password_hash) then return jsonb_build_object('error', 'CREDENCIALES'); end if;
  v_token := encode(privado.gen_random_bytes(32), 'hex');
  insert into comun.sesiones (token_hash, usuario_id, expires_at) values (privado.digest(v_token, 'sha256'), u.id, now() + interval '12 hours');
  return jsonb_build_object('token', v_token);
end $f$;
-- Datos de ejemplo: un bar con un camarero y la cuenta de plataforma.
insert into comun.negocios (slug, nombre, tipo) values ('bar-ejemplo','Bar de ejemplo','multibar'), ('autonomialab','autonomIA Lab','plataforma');
insert into comun.usuarios (negocio_id,email,name,password_hash,must_change_password) values
 (1,'camarero@ejemplo.test','Camarero ejemplo',extensions.crypt('clave-camarero',extensions.gen_salt('bf',4)),false),
 (2,'plataforma@ejemplo.test','Plataforma ejemplo',extensions.crypt('clave-plataforma',extensions.gen_salt('bf',4)),false);
insert into multibar.personal_multibar values (1,1,'admin');
-- Ayudante común de enlaces de recuperación (copiado de Supabase, 19 oct).
CREATE FUNCTION privado.crear_enlace(p_usuario integer, p_minutos integer) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','comun','multibar','privado','pg_temp' AS $f$
declare v_token text;
begin
  if (select count(*) from comun.recuperaciones where usuario_id = p_usuario and created_at > now() - interval '1 hour') >= 3 then
    return null;
  end if;
  update comun.recuperaciones set usado_at = now() where usuario_id = p_usuario and usado_at is null;
  v_token := encode(privado.gen_random_bytes(32), 'hex');
  insert into comun.recuperaciones (token_hash, usuario_id, expires_at) values (privado.digest(v_token, 'sha256'), p_usuario, now() + make_interval(mins => p_minutos));
  return v_token;
end $f$;
